// Transformer en format compatible avec ton pipeline existant
const output = [];

for (const project of portfolioProjects.projects) {
  // 1. Document principal (équivalent à repository_overview)
  output.push({
    json: {
      pageContent: `# ${project.name}

**Description:** ${project.short_description}

**Langage principal:** ${project.language}
**Type:** ${project.category}
**URL:** ${project.url || 'Non disponible'}
**GitHub:** ${project.github_url || 'Non disponible'}
**Homepage:** ${project.homepage || 'Non disponible'}
**Statut:** ${project.status}

**Fonctionnalités principales:**
${project.features.map(f => `- ${f}`).join('\n')}

**Points forts:**
${project.highlights.map(h => `- ${h}`).join('\n')}

**Stack technique:** ${project.tech_stack.join(', ')}`,

      metadata: {
        type: "repository_overview",
        repo_name: project.name,
        repo_full_name: project.id,
        language: project.language,
        url: project.url,
        homepage: project.homepage,
        github_url: project.github_url,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        topics: project.tags,
        category: project.category
      }
    }
  });

  // 2. Document technique détaillé
  output.push({
    json: {
      pageContent: `Projet: ${project.name}

Stack technique: ${project.tech_stack.join(', ')}

Description: ${project.full_description}

${project.homepage ? `Demo disponible: ${project.homepage}` : 'Pas de demo'}

Type de projet: ${project.category}
Langage: ${project.language}

Technologies utilisées:
${Object.entries(project.technologies).map(([cat, techs]) => 
  `${cat}: ${techs.join(', ')}`
).join('\n')}`,

      metadata: {
        type: "technical_details",
        repo_name: project.name,
        language: project.language,
        tech_stack: project.tech_stack,
        category: project.category,
        has_demo: !!project.homepage
      }
    }
  });

  // 3. Document skills showcase
  output.push({
    json: {
      pageContent: `Compétences techniques démontrées dans le projet "${project.name}":

${project.tags.map(skill => `- ${skill}`).join('\n')}

Description du projet: ${project.full_description}

Ce projet illustre ma maîtrise de ${project.language} et mon expérience en ${project.category}.

Points forts:
${project.highlights.map(h => `- ${h}`).join('\n')}`,

      metadata: {
        type: "skills_showcase",
        repo_name: project.name,
        language: project.language,
        skills: project.tags,
        project_type: project.category
      }
    }
  });
}

// Ajouter les documents de contexte global
output.push({
  json: {
    pageContent: `# Portfolio de développeur

Je suis un développeur full-stack avec ${portfolioProjects.projects.length} projets principaux.

**Langages maîtrisés:** ${[...new Set(portfolioProjects.projects.map(p => p.language))].join(', ')}

**Technologies et compétences:** ${[...new Set(portfolioProjects.projects.flatMap(p => p.tags))].join(', ')}

**Domaines d'expertise:**
${[...new Set(portfolioProjects.projects.map(p => p.category))].map(cat => `- ${cat}`).join('\n')}

**Profil GitHub:** https://github.com/HardstyIe

Mon portfolio démontre une expertise variée en développement web, data science, et automatisation.`,

    metadata: {
      type: "portfolio_overview",
      category: "about",
      importance: "high",
